// --- HNSW RESOURCE MANAGEMENT ---

static ErlNifResourceType* HNSW_RES_TYPE = NULL;

typedef struct {
    fp_hnsw_index* index;
} hnsw_res;

static void hnsw_res_destructor(ErlNifEnv* env, void* obj) {
    hnsw_res* res = (hnsw_res*)obj;
    if (res->index) {
        fp_hnsw_free(res->index);
        res->index = NULL;
    }
}

// --- QUERY NIF WRAPPERS ---

static ERL_NIF_TERM nif_fp_query_gemv_columnar(ErlNifEnv* env, int argc, const ERL_NIF_TERM argv[]) {
    int dim_int;
    ErlNifUInt64 count, dim;

    if (!enif_get_uint64(env, argv[2], &count)) return enif_make_badarg(env);
    if (!enif_get_uint64(env, argv[3], &dim)) return enif_make_badarg(env);

    if (!enif_get_tuple(env, argv[0], &dim_int, NULL)) return enif_make_badarg(env);
    if ((size_t)dim_int != dim) return enif_make_badarg(env);

    ErlNifBinary query_bin;
    if (!enif_inspect_binary(env, argv[1], &query_bin)) return enif_make_badarg(env);
    if (query_bin.size != dim * 8) return enif_make_badarg(env);

    const double** columns = malloc(dim * sizeof(double*));
    if (!columns) return enif_make_badarg(env);

    const ERL_NIF_TERM* tuple_elements;
    if (!enif_get_tuple(env, argv[0], &dim_int, &tuple_elements)) {
        free(columns);
        return enif_make_badarg(env);
    }

    ErlNifBinary* col_bins = malloc(dim * sizeof(ErlNifBinary));
    if (!col_bins) {
        free(columns);
        return enif_make_badarg(env);
    }

    for (size_t d = 0; d < dim; d++) {
        if (!enif_inspect_binary(env, tuple_elements[d], &col_bins[d])) {
            free(columns);
            free(col_bins);
            return enif_make_badarg(env);
        }
        if (col_bins[d].size != count * 8) {
            free(columns);
            free(col_bins);
            return enif_make_badarg(env);
        }
        columns[d] = (const double*)col_bins[d].data;
    }

    ErlNifBinary scores_bin;
    if (!enif_alloc_binary(count * 8, &scores_bin)) {
        free(columns);
        free(col_bins);
        return enif_make_badarg(env);
    }

    fp_query_gemv_columnar_f64(
        columns,
        (const double*)query_bin.data,
        (double*)scores_bin.data,
        count,
        dim
    );

    free(columns);
    free(col_bins);

    return enif_make_binary(env, &scores_bin);
}

static ERL_NIF_TERM nif_fp_query_gemv_indexed(ErlNifEnv* env, int argc, const ERL_NIF_TERM argv[]) {
    int dim_int;
    ErlNifUInt64 count, dim;

    if (!enif_get_uint64(env, argv[3], &count)) return enif_make_badarg(env);
    if (!enif_get_uint64(env, argv[4], &dim)) return enif_make_badarg(env);

    if (!enif_get_tuple(env, argv[0], &dim_int, NULL)) return enif_make_badarg(env);
    if ((size_t)dim_int != dim) return enif_make_badarg(env);

    ErlNifBinary query_bin;
    if (!enif_inspect_binary(env, argv[1], &query_bin)) return enif_make_badarg(env);
    if (query_bin.size != dim * 8) return enif_make_badarg(env);

    ErlNifBinary indices_bin;
    if (!enif_inspect_binary(env, argv[2], &indices_bin)) return enif_make_badarg(env);
    size_t num_indices = indices_bin.size / 4;

    const double** columns = malloc(dim * sizeof(double*));
    if (!columns) return enif_make_badarg(env);

    const ERL_NIF_TERM* tuple_elements;
    if (!enif_get_tuple(env, argv[0], &dim_int, &tuple_elements)) {
        free(columns);
        return enif_make_badarg(env);
    }

    ErlNifBinary* col_bins = malloc(dim * sizeof(ErlNifBinary));
    if (!col_bins) {
        free(columns);
        return enif_make_badarg(env);
    }

    for (size_t d = 0; d < dim; d++) {
        if (!enif_inspect_binary(env, tuple_elements[d], &col_bins[d])) {
            free(columns);
            free(col_bins);
            return enif_make_badarg(env);
        }
        if (col_bins[d].size != count * 8) {
            free(columns);
            free(col_bins);
            return enif_make_badarg(env);
        }
        columns[d] = (const double*)col_bins[d].data;
    }

    ErlNifBinary scores_bin;
    if (!enif_alloc_binary(num_indices * 8, &scores_bin)) {
        free(columns);
        free(col_bins);
        return enif_make_badarg(env);
    }

    fp_query_gemv_indexed_f64(
        columns,
        (const double*)query_bin.data,
        (const int32_t*)indices_bin.data,
        num_indices,
        (double*)scores_bin.data,
        count,
        dim
    );

    free(columns);
    free(col_bins);

    return enif_make_binary(env, &scores_bin);
}

static ERL_NIF_TERM nif_fp_query_topk(ErlNifEnv* env, int argc, const ERL_NIF_TERM argv[]) {
    ErlNifBinary scores_bin;
    ErlNifUInt64 count, k;
    double threshold;

    if (!enif_inspect_binary(env, argv[0], &scores_bin)) return enif_make_badarg(env);
    if (!enif_get_uint64(env, argv[1], &count)) return enif_make_badarg(env);
    if (!enif_get_uint64(env, argv[2], &k)) return enif_make_badarg(env);
    if (!enif_get_double(env, argv[3], &threshold)) return enif_make_badarg(env);

    if (scores_bin.size != count * 8) return enif_make_badarg(env);

    ErlNifBinary indices_bin, result_scores_bin;
    if (!enif_alloc_binary(k * 4, &indices_bin)) return enif_make_badarg(env);
    if (!enif_alloc_binary(k * 8, &result_scores_bin)) {
        enif_release_binary(&indices_bin);
        return enif_make_badarg(env);
    }

    size_t result_count = fp_query_topk_f64(
        (const double*)scores_bin.data,
        count,
        k,
        threshold,
        (int32_t*)indices_bin.data,
        (double*)result_scores_bin.data
    );

    if (result_count < k) {
        enif_realloc_binary(&indices_bin, result_count * 4);
        enif_realloc_binary(&result_scores_bin, result_count * 8);
    }

    return enif_make_tuple3(env,
        enif_make_uint64(env, result_count),
        enif_make_binary(env, &indices_bin),
        enif_make_binary(env, &result_scores_bin)
    );
}

// --- QUANTIZATION NIF WRAPPERS ---

static ERL_NIF_TERM nif_fp_quantize_f64_to_u8(ErlNifEnv* env, int argc, const ERL_NIF_TERM argv[]) {
    ErlNifBinary in_bin;
    double min_val, inv_scale;

    if (!enif_inspect_binary(env, argv[0], &in_bin)) return enif_make_badarg(env);
    if (!enif_get_double(env, argv[1], &min_val)) return enif_make_badarg(env);
    if (!enif_get_double(env, argv[2], &inv_scale)) return enif_make_badarg(env);

    size_t count = in_bin.size / 8;
    ErlNifBinary out_bin;
    if (!enif_alloc_binary(count, &out_bin)) return enif_make_badarg(env);

    fp_quantize_f64_to_u8((const double*)in_bin.data, (uint8_t*)out_bin.data, count, min_val, inv_scale);

    return enif_make_binary(env, &out_bin);
}

static ERL_NIF_TERM nif_fp_query_gemv_quantized(ErlNifEnv* env, int argc, const ERL_NIF_TERM argv[]) {
    int dim_int;
    ErlNifUInt64 count, dim;
    double bias;

    if (!enif_get_double(env, argv[2], &bias)) return enif_make_badarg(env);
    if (!enif_get_uint64(env, argv[3], &count)) return enif_make_badarg(env);
    if (!enif_get_uint64(env, argv[4], &dim)) return enif_make_badarg(env);

    if (!enif_get_tuple(env, argv[0], &dim_int, NULL)) return enif_make_badarg(env);
    if ((size_t)dim_int != dim) return enif_make_badarg(env);

    ErlNifBinary query_bin;
    if (!enif_inspect_binary(env, argv[1], &query_bin)) return enif_make_badarg(env);
    if (query_bin.size != dim * 8) return enif_make_badarg(env);

    const uint8_t** columns = malloc(dim * sizeof(uint8_t*));
    if (!columns) return enif_make_badarg(env);

    const ERL_NIF_TERM* tuple_elements;
    enif_get_tuple(env, argv[0], &dim_int, &tuple_elements);

    ErlNifBinary* col_bins = malloc(dim * sizeof(ErlNifBinary));
    if (!col_bins) { free(columns); return enif_make_badarg(env); }

    for (size_t d = 0; d < dim; d++) {
        if (!enif_inspect_binary(env, tuple_elements[d], &col_bins[d]) || col_bins[d].size != count) {
            free(columns); free(col_bins); return enif_make_badarg(env);
        }
        columns[d] = (const uint8_t*)col_bins[d].data;
    }

    ErlNifBinary scores_bin;
    if (!enif_alloc_binary(count * 8, &scores_bin)) {
        free(columns); free(col_bins); return enif_make_badarg(env);
    }

    fp_query_gemv_quantized_f64_u8(
        columns,
        (const double*)query_bin.data,
        bias,
        (double*)scores_bin.data,
        count,
        dim
    );

    free(columns);
    free(col_bins);

    return enif_make_binary(env, &scores_bin);
}

static ERL_NIF_TERM nif_fp_sparse_dotp(ErlNifEnv* env, int argc, const ERL_NIF_TERM argv[]) {
    // argv[0]: indices_a, argv[1]: values_a
    // argv[2]: indices_b, argv[3]: values_b

    ErlNifBinary ind_a, val_a, ind_b, val_b;

    if (!enif_inspect_binary(env, argv[0], &ind_a)) return enif_make_badarg(env);
    if (!enif_inspect_binary(env, argv[1], &val_a)) return enif_make_badarg(env);
    if (!enif_inspect_binary(env, argv[2], &ind_b)) return enif_make_badarg(env);
    if (!enif_inspect_binary(env, argv[3], &val_b)) return enif_make_badarg(env);

    size_t len_a = ind_a.size / 4;
    size_t len_b = ind_b.size / 4;

    double dot = fp_sparse_dotp_f64(
        (const int32_t*)ind_a.data,
        (const double*)val_a.data,
        len_a,
        (const int32_t*)ind_b.data,
        (const double*)val_b.data,
        len_b
    );

    return enif_make_double(env, dot);
}

static ERL_NIF_TERM nif_fp_hnsw_create(ErlNifEnv* env, int argc, const ERL_NIF_TERM argv[]) {
    int dim, M, ef_construction;
    ErlNifUInt64 capacity;

    if (!enif_get_int(env, argv[0], &dim)) return enif_make_badarg(env);
    if (!enif_get_int(env, argv[1], &M)) return enif_make_badarg(env);
    if (!enif_get_int(env, argv[2], &ef_construction)) return enif_make_badarg(env);
    if (!enif_get_uint64(env, argv[3], &capacity)) return enif_make_badarg(env);

    hnsw_res* res = enif_alloc_resource(HNSW_RES_TYPE, sizeof(hnsw_res));
    res->index = fp_hnsw_create(dim, M, ef_construction, (size_t)capacity);

    if (!res->index) {
        enif_release_resource(res);
        return enif_make_badarg(env);
    }

    ERL_NIF_TERM term = enif_make_resource(env, res);
    enif_release_resource(res);
    return term;
}

static ERL_NIF_TERM nif_fp_hnsw_insert(ErlNifEnv* env, int argc, const ERL_NIF_TERM argv[]) {
    hnsw_res* res;
    int vector_idx;
    ErlNifBinary vec_bin;
    ErlNifUInt64 db_count;

    if (!enif_get_resource(env, argv[0], HNSW_RES_TYPE, (void**)&res)) return enif_make_badarg(env);
    if (!enif_get_int(env, argv[1], &vector_idx)) return enif_make_badarg(env);
    if (!enif_inspect_binary(env, argv[2], &vec_bin)) return enif_make_badarg(env);
    if (!enif_get_uint64(env, argv[4], &db_count)) return enif_make_badarg(env);

    int dim = res->index->dim;
    if (vec_bin.size != (size_t)dim * 8) return enif_make_badarg(env);

    const double** columns = malloc(dim * sizeof(double*));
    int dim_int;
    const ERL_NIF_TERM* tuple_elements;
    enif_get_tuple(env, argv[3], &dim_int, &tuple_elements);
    
    ErlNifBinary* col_bins = malloc(dim * sizeof(ErlNifBinary));
    for (int d = 0; d < dim; d++) {
        enif_inspect_binary(env, tuple_elements[d], &col_bins[d]);
        columns[d] = (const double*)col_bins[d].data;
    }

    fp_hnsw_insert(res->index, vector_idx, (const double*)vec_bin.data, columns, (size_t)db_count);

    free(columns);
    free(col_bins);

    return enif_make_atom(env, "ok");
}

static ERL_NIF_TERM nif_fp_hnsw_search(ErlNifEnv* env, int argc, const ERL_NIF_TERM argv[]) {
    hnsw_res* res;
    ErlNifBinary query_bin;
    int k, ef_search;
    ErlNifUInt64 db_count;

    if (!enif_get_resource(env, argv[0], HNSW_RES_TYPE, (void**)&res)) return enif_make_badarg(env);
    if (!enif_inspect_binary(env, argv[1], &query_bin)) return enif_make_badarg(env);
    if (!enif_get_int(env, argv[2], &k)) return enif_make_badarg(env);
    if (!enif_get_int(env, argv[3], &ef_search)) return enif_make_badarg(env);
    if (!enif_get_uint64(env, argv[5], &db_count)) return enif_make_badarg(env);

    int dim = res->index->dim;
    if (query_bin.size != (size_t)dim * 8) return enif_make_badarg(env);

    const double** columns = malloc(dim * sizeof(double*));
    int dim_int;
    const ERL_NIF_TERM* tuple_elements;
    enif_get_tuple(env, argv[4], &dim_int, &tuple_elements);
    
    ErlNifBinary* col_bins = malloc(dim * sizeof(ErlNifBinary));
    for (int d = 0; d < dim; d++) {
        enif_inspect_binary(env, tuple_elements[d], &col_bins[d]);
        columns[d] = (const double*)col_bins[d].data;
    }

    int32_t* results_indices = malloc(k * sizeof(int32_t));
    double* results_scores = malloc(k * sizeof(double));

    size_t result_count = fp_hnsw_search(
        res->index,
        (const double*)query_bin.data,
        k,
        ef_search,
        columns,
        (size_t)db_count,
        results_indices,
        results_scores
    );

    free(columns);
    free(col_bins);

    ErlNifBinary indices_bin, scores_bin;
    enif_alloc_binary(result_count * 4, &indices_bin);
    memcpy(indices_bin.data, results_indices, result_count * 4);
    
    enif_alloc_binary(result_count * 8, &scores_bin);
    memcpy(scores_bin.data, results_scores, result_count * 8);

    free(results_indices);
    free(results_scores);

    return enif_make_tuple3(env,
        enif_make_uint64(env, result_count),
        enif_make_binary(env, &indices_bin),
        enif_make_binary(env, &scores_bin)
    );
}

// --- BLAKE3 NIF WRAPPER ---

static ERL_NIF_TERM nif_fp_blake3_hash(ErlNifEnv* env, int argc, const ERL_NIF_TERM argv[]) {
    ErlNifBinary input_bin;
    if (!enif_inspect_binary(env, argv[0], &input_bin)) return enif_make_badarg(env);

    ErlNifBinary output_bin;
    if (!enif_alloc_binary(32, &output_bin)) return enif_make_badarg(env);

    fp_blake3_hash(input_bin.data, input_bin.size, output_bin.data);

    return enif_make_binary(env, &output_bin);
}

