static int load(ErlNifEnv* env, void** priv_data, ERL_NIF_TERM load_info);
static void unload(ErlNifEnv* env, void* priv_data);

static int load(ErlNifEnv* env, void** priv_data, ERL_NIF_TERM load_info) {
    // Initialize HNSW resource type
    HNSW_RES_TYPE = enif_open_resource_type(env, NULL, "hnsw_index", hnsw_res_destructor, ERL_NIF_RT_CREATE, NULL);
    
    // Initialize Job system resources
    if (fp_job_load(env) != 0) {
        return -1;
    }

    return load_resources(env, priv_data, load_info);
}

static void unload(ErlNifEnv* env, void* priv_data) {
    (void)priv_data;
    fp_job_unload(env);
}

static int upgrade(ErlNifEnv* env, void** priv_data, void** old_priv_data, ERL_NIF_TERM load_info) {
    return 0;
}

